import { Mark, markInputRule } from '@tiptap/core';
import { __ } from '~/locale';
import { PARSE_HTML_PRIORITY_HIGH } from '../constants';

export default Mark.create({
  name: 'mathInline',

  addAttributes() {
    return {
      mathStyle: {
        default: 'inline',
        rendered: false,
      },
      dollarMath: {
        default: false,
        rendered: false,
      },
    };
  },

  parseHTML() {
    return [
      // Matches HTML generated by Banzai::Filter::MarkdownFilter for $`math`$
      {
        tag: 'code[data-math-style=inline]',
        priority: PARSE_HTML_PRIORITY_HIGH,
      },
      // Matches HTML generated by Banzai::Filter::MarkdownFilter for $math$ and $$math$$
      {
        tag: 'span[data-math-style]',
        priority: PARSE_HTML_PRIORITY_HIGH,
        getAttrs: (element) => ({ dollarMath: true, mathStyle: element.dataset.mathStyle }),
      },
      // Matches HTML after being transformed by app/assets/javascripts/behaviors/markdown/render_math.js
      {
        tag: 'span.katex',
        contentElement: 'annotation[encoding="application/x-tex"]',
      },
    ];
  },

  renderHTML({ mark, HTMLAttributes }) {
    return [
      'code',
      {
        title: mark.attrs.mathStyle === 'display' ? __('Display math') : __('Inline math'),
        'data-toggle': 'tooltip',
        class: 'gl-shadow-inner-1-gray-400',
        ...HTMLAttributes,
      },
      0,
    ];
  },

  addInputRules() {
    const inputRegex = /(?:^|\s)\$`([^`]+)`\$$/gm;

    return [markInputRule({ find: inputRegex, type: this.type })];
  },
});
